1	import type { GrammarEntry } from "../../grammar/types";
2	import type { CompositionGameItem, RandomSource } from "../types";
3	import { sampleWithoutReplacement } from "./sampling";
4	
5	type ExampleWithWords = GrammarEntry["examples"][number] & {
6		words: NonNullable<GrammarEntry["examples"][number]["words"]>;
7	};
8	
9	/**
10	 * The example a composition round builds from: the entry's own
11	 * `cards.application.correctExample`-indexed example if it carries a
12	 * `words` breakdown, falling back to the first example in `examples` that
13	 * does. `GrammarCardGenerator.ts` itself accesses `correctExample` with
14	 * `?.` for the same reason — the index can be out of range.
15	 */
16	function exampleWithWordsOf(entry: GrammarEntry): ExampleWithWords | null {
17		const canonical = entry.examples[entry.cards.application.correctExample];
18		if (canonical?.words) return canonical as ExampleWithWords;
19	
20		return (
21			(entry.examples.find((example) => example.words) as
22				| ExampleWithWords
23				| undefined) ?? null
24		);
25	}
26	
27	/**
28	 * Builds a round of sentence-composition items from an already-filtered
29	 * set of unlocked `GrammarEntry` values (task 3.2 resolves "currently
30	 * unlocked" via `GrammarLessonService.getUnlockedGrammarPoints()` and
31	 * passes the result in) — this function is deliberately a plain function
32	 * over that array, not a `GameItemSource`: the interface promises
33	 * per-item card eligibility, and "unlocked" is a set-level computation
34	 * over prerequisites and a learned prefix, not that. See CONTEXT.md.
35	 *
36	 * An entry with no example carrying a `words` breakdown is excluded
37	 * rather than producing a broken item.
38	 */
39	export function selectCompositionRound(
40		unlockedGrammarPoints: readonly GrammarEntry[],
41		count: number,
42		rng: RandomSource = Math.random,
43	): CompositionGameItem[] {
44		const eligible: CompositionGameItem[] = [];
45	
46		for (const entry of unlockedGrammarPoints) {
47			const example = exampleWithWordsOf(entry);
48			if (!example) continue;
49	
50			const correctOrder = example.words.map((word) => word.thai);
51			const tiles = sampleWithoutReplacement(correctOrder, correctOrder.length, {
52				rng,
53			});
54	
55			eligible.push({
56				kind: "composition",
57				grammarId: entry.id,
58				englishMeaning: example.english,
59				tiles,
60				correctOrder,
61				challengeDirection: "build",
62			});
63		}
64	
65		return sampleWithoutReplacement(eligible, count, { rng });
66	}
