280	 * draws from currently-unlocked grammar points, which is not a
281	 * `GameCardPool` partition at all (see `selectCompositionRound`).
282	 */
283	export interface CompositionHistoryEntry extends GameHistoryEntryBase {
284		readonly kind: "composition";
285	}
286	
287	/**
288	 * A discriminated union on `kind`, and `kind` is **required** on both
289	 * variants. Entries persisted before this field existed are normalized to
290	 * `"practice"` once, on read, by `StorageGameHistoryRepository.list()` — so
291	 * no consumer anywhere ever sees an entry without a `kind`, and none needs
292	 * its own copy of that back-compat rule. An *optional* discriminant would
293	 * be the weak version of this: `entry.kind === "practice"` is `false` for
294	 * every legacy entry, which is exactly the shape a consumer gets wrong by
295	 * writing the natural code.
296	 */
