70	} from "../../infrastructure/persistence/JsonStore";
71	import { InMemoryStorage } from "../../infrastructure/persistence/Storage";
72	import { StorageCardRepository } from "../../infrastructure/persistence/StorageCardRepository";
73	import { StorageGameHistoryRepository } from "../../infrastructure/persistence/StorageGameHistoryRepository";
74	import { StorageLearnerStateRepository } from "../../infrastructure/persistence/StorageLearnerStateRepository";
75	import { AppContext, type AppContextValue } from "../context/AppContext";
76	
77	// --- localStorage fake (jsdom's own is unreliable here, see module docs) ---
78	
79	export class FakeLocalStorage implements Storage {
80		private store = new Map<string, string>();
81	
82		get length(): number {
83			return this.store.size;
84		}
85	
86		clear(): void {
87			this.store.clear();
88		}
89	
90		getItem(key: string): string | null {
91			return this.store.has(key) ? (this.store.get(key) as string) : null;
92		}
93	
94		key(index: number): string | null {
95			return Array.from(this.store.keys())[index] ?? null;
96		}
97	
98		removeItem(key: string): void {
99			this.store.delete(key);
100		}
101	
102		setItem(key: string, value: string): void {
103			this.store.set(key, value);
104		}
105	}
106	
107	let fakeLocalStorage = new FakeLocalStorage();
108	
109	/** The per-test `localStorage` stand-in installed on `globalThis`. */
110	export function getFakeLocalStorage(): FakeLocalStorage {
111		return fakeLocalStorage;
112	}
113	
114	// --- Audio stub (jsdom throws synchronously from `play()`) ---
115	
116	export class StubAudio {
117		static createdUrls: string[] = [];
118		currentTime = 0;
119	
120		constructor(readonly src?: string) {
121			StubAudio.createdUrls.push(src ?? "");
122		}
123	
124		play(): Promise<void> {
125			return Promise.resolve();
126		}
127	
128		pause(): void {}
129	}
130	
131	/** URLs passed to `new Audio(url)` since the current test began. */
132	export function createdAudioUrls(): readonly string[] {
133		return StubAudio.createdUrls;
134	}
135	
136	// --- Canvas 2D stub (jsdom has no 2D context without the canvas package) ---
137	
138	export const canvas2d = {
139		clearRect: vi.fn(),
140		beginPath: vi.fn(),
141		moveTo: vi.fn(),
142		lineTo: vi.fn(),
143		stroke: vi.fn(),
144		lineCap: "round",
145		lineJoin: "round",
146		lineWidth: 4,
147		strokeStyle: "",
148	};
149	
150	beforeEach(() => {
151		fakeLocalStorage = new FakeLocalStorage();
152		globalThis.localStorage = fakeLocalStorage;
153		globalThis.Audio = StubAudio as unknown as typeof Audio;
154		StubAudio.createdUrls = [];
155		canvas2d.clearRect.mockClear();
156		canvas2d.beginPath.mockClear();
157		canvas2d.moveTo.mockClear();
158		canvas2d.lineTo.mockClear();
159		canvas2d.stroke.mockClear();
160		if (typeof HTMLMediaElement !== "undefined") {
161			HTMLMediaElement.prototype.play = () => Promise.resolve();
162			HTMLMediaElement.prototype.pause = () => {};
163		}
164		if (typeof HTMLCanvasElement !== "undefined") {
165			HTMLCanvasElement.prototype.getContext = (() =>
166				canvas2d) as unknown as HTMLCanvasElement["getContext"];
167		}
168	});
169	
170	afterEach(() => {
171		cleanup();
172		Reflect.deleteProperty(globalThis, "localStorage");
173	});
174	
175	// --- Fixtures ---
176	
177	const DEFAULT_SRS = {
178		easeFactor: 2.0,
179		interval: 10,
180		repetitions: 0,
181		learningStep: 1,
182		nextReviewDate: "2026-01-01T00:00:00.000Z",
183		lastReviewDate: null,
184		lapseCount: 0,
185	};
186	
187	/**
188	 * One script card for `symbolCharacter` — enough to make that symbol
189	 * eligible (eligibility is card-driven; content still comes from
190	 * `symbols.ts`, so pass characters that exist there, e.g. "ม", "น", "ง").
191	 */
192	export function makeScriptCard(symbolCharacter: string): ScriptPropertyCard {
193		return ScriptPropertyCard.fromDTO({
194			id: `${symbolCharacter}-recognition`,
195			question: `What sound does ${symbolCharacter} make?`,
196			correctAnswer: "answer",
197			choices: ["answer", "other"],
198			srs: { ...DEFAULT_SRS },
199			symbolCharacter,
200			property: "recognition",
201			lessonNumber: 1,
202		});
203	}
204	
205	/**
206	 * A script card with an explicit SRS history — for weighting/weak-item tests.
207	 */
208	export function scriptCardWith(
209		symbolCharacter: string,
210		easeFactor: number,
211		lapseCount: number,
212		repetitions: number,
213	): ScriptPropertyCard {
214		return ScriptPropertyCard.fromDTO({
215			id: `${symbolCharacter}-recognition`,
216			question: "question",
217			correctAnswer: "answer",
218			choices: ["answer"],
219			srs: {
220				easeFactor,
221				interval: 10,
222				repetitions,
223				learningStep: null,
224				nextReviewDate: "2026-01-01T00:00:00.000Z",
225				lastReviewDate: "2026-01-01T00:00:00.000Z",
226				lapseCount,
227			},
228			symbolCharacter,
229			property: "recognition",
230			lessonNumber: 1,
231		});
232	}
233	
234	/**
235	 * One sentence review card for `sentenceId` — enough to make that sentence
236	 * eligible (eligibility is card-driven; content still comes from
237	 * `sentences.json`, so pass ids that exist there, e.g. "basic-001").
238	 */
239	export function makeSentenceCard(sentenceId: string): SentenceReviewCard {
240		return SentenceReviewCard.fromDTO({
241			id: `sentence:${sentenceId}:readingComprehension`,
242			question: `question for ${sentenceId}`,
243			correctAnswer: "answer",
244			choices: ["answer", "other"],
245			srs: { ...DEFAULT_SRS },
246			sentenceId,
247			property: "readingComprehension",
248		});
249	}
250	
251	/**
252	 * One `toneIdentification` vocab card for `thai` — enough to make that word
253	 * eligible for tone practice (eligibility is card-driven; the item's
254	 * content still comes from the matching `VocabEntry`, so pass Thai words
255	 * that exist in `vocabulary.json`, e.g. "ที่", "ได้", "จะ", "นี้").
256	 *
257	 * The card carries the word's real syllables, exactly as
258	 * `VocabCardGenerator` writes them, so a fixture can never accidentally
259	 * prove more than production does — but nothing reads them: a card
260	 * persisted before that field existed has `syllables === undefined`, which
261	 * is why `ToneGameItemSource` sources its content from the entry instead
262	 * (see CONTEXT.md).
263	 */
264	export function makeToneVocabCard(thai: string): VocabCard {
265		const entry = (vocabularyData as VocabEntry[]).find(
266			(word) => word.thai === thai,
267		);
268		if (!entry) {
269			throw new Error(`no vocabulary entry for "${thai}"`);
270		}
271		return VocabCard.fromDTO({
272			id: `vocab:${thai}:toneIdentification`,
273			question: `What is the tone pattern of ${thai}?`,
274			correctAnswer: "answer",
275			choices: ["answer", "other"],
276			srs: { ...DEFAULT_SRS },
277			promptWord: thai,
278			property: "toneIdentification",
279			syllables: toneSyllablesOf(entry),
280		});
