282	
283	/** A `GameItem` with a pre-assigned direction, for fixed-round tests. */
284	export function makeSymbolItem(
285		symbolCharacter: string,
286		challengeDirection: SymbolChallengeDirection,
287		overrides: Partial<Omit<SymbolItemContent, "kind">> = {},
288	): GameItem {
289		return {
290			kind: "symbol",
291			symbolCharacter,
292			promptText: symbolCharacter,
293			correctAnswer: `${symbolCharacter} name`,
294			audioUrl: `/audio/${symbolCharacter}.mp3`,
295			...overrides,
296			challengeDirection,
297		};
298	}
299	
300	/** A persisted history entry, for seeding history stores. */
301	export function makeHistoryEntry(
302		overrides: Partial<GameHistoryEntry> = {},
303	): GameHistoryEntry {
304		return {
305			kind: "practice",
306			id: "entry-1",
307			playedAt: "2026-09-01T10:00:00.000Z",
308			pools: ["script"],
309			itemCount: 4,
310			summary: {
311				ratingCounts: { 1: 0, 2: 1, 3: 0, 4: 2, 5: 1 },
312				ratedCount: 4,
313				accuracy: 75,
314			},
315			...overrides,
316		};
317	}
318	
319	/** A `JsonStore` whose every load reports corrupt — the unavailable case. */
320	export class CorruptJsonStore<T> implements JsonStore<T> {
321		load(): JsonStoreLoadResult<T> {
322			return { status: "corrupt" };
323		}
324	
325		save(): JsonStoreSaveResult {
326			return { status: "ok" };
327		}
328	}
329	
330	// --- Game use-case factories ---
331	
332	export interface MakeGameOptions {
333		symbols?: readonly string[];
334		historyStore?: JsonStore<GameHistoryEntry[]>;
335	}
336	
337	/** A real `PlayGameUseCase` over in-memory persistence. */
338	export function makeGame(options: MakeGameOptions = {}): PlayGameUseCase {
339		const cardRepo = new StorageCardRepository(new InMemoryStorage());
340		cardRepo.saveAll((options.symbols ?? []).map(makeScriptCard));
341		return new PlayGameUseCase(
342			new GameItemSelectionService([new SymbolGameItemSource(cardRepo)]),
343			new StorageGameHistoryRepository(
344				options.historyStore ?? new InMemoryJsonStore<GameHistoryEntry[]>(),
345			),
346			// No composition rounds from this factory: it wires one symbol source
347			// and no grammar, so an empty unlocked set is the honest answer.
348			() => [],
349		);
350	}
351	
352	class FixedRoundGame extends PlayGameUseCase {
353		constructor(
354			private readonly fixedItems: readonly GameItem[],
355			selection: GameItemSelectionService,
356			historyRepository: GameHistoryRepository,
357		) {
358			super(selection, historyRepository, () => []);
359		}
360	
361		override startRound(config: GameRoundConfig): GameItem[] {
362			return this.fixedRound(config.itemCount);
363		}
364	
365		/**
366		 * Composition rounds are fixed the same way practice rounds are, so a
367		 * page test can drive either mode from one list of pre-built items.
368		 */
369		override startCompositionRound(count: number): GameItem[] {
370			return this.fixedRound(count);
371		}
372	
373		private fixedRound(count: number): GameItem[] {
374			return this.fixedItems.slice(
375				0,
376				normalizeRequestedCount(count, this.fixedItems.length),
377			);
378		}
379	}
380	
381	/**
382	 * A `PlayGameUseCase` whose rounds are exactly `items`, in order, with the
383	 * directions the test pre-assigned — everything else (rating, finishing,
384	 * history) stays real.
385	 */
386	export function makeFixedRoundGame(
387		items: readonly GameItem[],
388		options: Pick<MakeGameOptions, "historyStore"> = {},
389	): { game: PlayGameUseCase; historyStore: JsonStore<GameHistoryEntry[]> } {
390		const historyStore =
391			options.historyStore ?? new InMemoryJsonStore<GameHistoryEntry[]>();
392		const cardRepo = new StorageCardRepository(new InMemoryStorage());
393		const game = new FixedRoundGame(
394			items,
395			new GameItemSelectionService([new SymbolGameItemSource(cardRepo)]),
396			new StorageGameHistoryRepository(historyStore),
397		);
398		return { game, historyStore };
399	}
400	
401	// --- The harness itself ---
402	
403	export interface AppHarness {
404		value: AppContextValue;
405		storage: InMemoryStorage;
406		cardRepo: StorageCardRepository;
407		historyStore: InMemoryJsonStore<GameHistoryEntry[]>;
408		game: PlayGameUseCase;
409	}
410	
411	export interface MakeAppValueOptions {
