export function makeToneVocabCard(thai: string): VocabCard {
	const entry = (vocabularyData as VocabEntry[]).find(
		(word) => word.thai === thai,
	);
	if (!entry) {
		throw new Error(`no vocabulary entry for "${thai}"`);
