	// --- Task 2.3: Tone Identification ---

	// Four real vocabulary entries, each with a determinable tone, so a
	// seeded `toneIdentification` card makes exactly four words eligible.
	const TONE_WORDS = ["ที่", "ได้", "จะ", "นี้"] as const;
